      "fullUrl": "https://example.org/fhir/Observation/observation-10",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-10",
        "status": "final",
        "code": {
          "text": "Patient-reported ocular negatives"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No eye discharge, gritty sensation, or itch. No flashes, floaters, curtain, or visual field loss."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-11",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-11",
        "status": "final",
        "code": {
          "text": "Eye inspection"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Mild ciliary flush around the left limbus. No obvious discharge or lid swelling. Right eye white and quiet."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-12",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-12",
        "status": "final",
        "code": {
          "text": "Pupils and relative afferent pupillary defect"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Pupils equal, round, and reactive. No relative afferent pupillary defect."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-13",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-13",
        "status": "final",
        "code": {
          "text": "Extraocular movements and diplopia"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Extraocular movements full; no diplopia."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-14",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-14",
        "status": "final",
        "code": {
          "text": "Confrontation visual fields"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Grossly normal in both eyes."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-15",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-15",
        "status": "final",
        "code": {
          "text": "Undilated fundoscopy"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Limited undilated examination. Discs sharp in both eyes; no obvious haemorrhage or exudates; maculae grossly normal; no clear retinal detachment."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-16",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-16",
        "status": "final",
        "code": {
          "text": "Cornea and anterior chamber examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Cornea grossly clear; anterior chamber depth appears normal; no hypopyon seen with torch."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-17",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-17",
        "status": "final",
        "code": {
          "text": "Periocular skin examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No periocular rash."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-18",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-18",
        "status": "final",
        "code": {
          "text": "General appearance"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Well appearing; no acute distress."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-19",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-19",
        "status": "final",
        "code": {
          "text": "Relevant patient-reported medical history"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No known autoimmune diagnosis. Denies arthritis, back pain, mouth or genital ulcers, diarrhoea, psoriasis, chronic cough, renal disease, or tuberculosis exposure. No known glaucoma, cataract surgery, or eye trauma."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-20",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-20",
        "status": "final",
        "code": {
          "text": "Intraocular pressure"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Normal, as recorded at the hospital eye clinic."
      }
