            "text": "500–1000 mg orally up to four times daily as needed for eye discomfort; maximum 4 g in 24 hours.",
            "route": {
              "text": "oral"
            },
            "asNeededBoolean": true,
            "timing": {
              "repeat": {
                "frequency": 4,
                "period": 1,
                "periodUnit": "d"
              }
            },
            "doseAndRate": [
              {
                "doseRange": {
