                    "value": 500,
                    "unit": "mg"
                  },
                  "high": {
                    "value": 1000,
                    "unit": "mg"
                  }
                }
              }
            ],
            "maxDosePerPeriod": {
              "numerator": {
                "value": 4,
                "unit": "g"
              },
              "denominator": {
