        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosage": [
          {
            "text": "One drop every hour while awake; number of drops per administration not specified.",
            "route": {
              "text": "ophthalmic"
            },
            "timing": {
              "repeat": {
                "frequency": 1,
                "period": 1,
                "periodUnit": "h",
                "when": [
                  "WAKE"
                ]
              }
            }
          }
        ],
        "note": [
          {
            "text": "Started by the hospital eye clinic for confirmed left anterior uveitis."
          }
        ]
      }
    },
    {
